import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.CVt6dz2a.js";const f=JSON.parse('{"title":"EP.20 视觉回归：让机器玩找茬","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.20-visual-regression.md","filePath":"comics/EP.20-visual-regression.md","lastUpdated":1793881879000}'),d={name:"comics/EP.20-visual-regression.md"};function o(l,t,s,n,h,u){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="ep-20-视觉回归-让机器玩找茬" tabindex="-1">EP.20 视觉回归：让机器玩找茬 <a class="header-anchor" href="#ep-20-视觉回归-让机器玩找茬" aria-label="Permalink to &quot;EP.20 视觉回归：让机器玩找茬&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/20-testing-quality/basics">20.1 基础入门：3D 页面的可测性设计</a> 延伸阅读：<a href="./../guide/20-testing-quality/advanced">进阶篇</a> · <a href="./../guide/20-testing-quality/practice">实战篇</a> 动手演示：本模块无独立 3D 演示页，测试对象是 <a href="./../public/demos/digital-twin/campus-twin.html">campus-twin 园区数字孪生</a>，门禁配置见实战篇</p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>每次改版，像素酱都要肉眼回归 20 个页面。第 23 次对到凌晨两点，眼睛看花，漏掉一处 2 像素的阴影偏移——上线后被用户截图投诉。</td></tr><tr><td>② 揭秘</td><td>码叔点破：视觉回归就是让机器玩找茬——基线截图随仓库提交，CI 现场拍新图，逐像素对比出 diff 图，差异超阈值就红灯。前提是固定种子、冻结动画再截图。</td></tr><tr><td>③ 实证</td><td>门禁上岗第一周就立功：有人改错阴影参数，CI 秒出 diff 图，红块精确圈在阴影区域，结构与性能门禁保持全绿，review 十秒定位。</td></tr><tr><td>④ 结案</td><td>坑点清单：种子不固定基线永远对不上、Mac 生成的基线在 Linux CI 全挂、虚机帧时间硬卡 33ms 误伤一片。码叔总结：门禁不是让人怕，是让人信。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-肉眼回归为什么必然失败" tabindex="-1">① 肉眼回归为什么必然失败 <a class="header-anchor" href="#_1-肉眼回归为什么必然失败" aria-label="Permalink to &quot;① 肉眼回归为什么必然失败&quot;">​</a></h3><p>3D 页面的输出是一张没有语义的像素画布，回归只能靠&quot;看&quot;。人眼盯 20 个页面，注意力衰减、前后记忆模糊，2 像素级的偏移根本不可靠。更糟的是它<strong>不可规模化</strong>——页面翻倍，凌晨也跟着翻倍。出路是把&quot;看&quot;变成&quot;比&quot;：机器不疲劳、不记得、只看像素差。</p><h3 id="_2-视觉回归流水线" tabindex="-1">② 视觉回归流水线 <a class="header-anchor" href="#_2-视觉回归流水线" aria-label="Permalink to &quot;② 视觉回归流水线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>做什么</th><th>关键配置</th></tr></thead><tbody><tr><td>拍基线</td><td>首次运行存标准截图</td><td>与 CI 同容器生成，随仓库提交</td></tr><tr><td>拍新图</td><td>每次 CI 现场截图</td><td>锁 viewport、deviceScaleFactor</td></tr><tr><td>对比</td><td>逐像素算差异</td><td><code>maxDiffPixelRatio: 0.01</code> 容忍噪声</td></tr><tr><td>出图</td><td>失败时产 expected/actual/diff 三图</td><td>diff 里差异像素染红</td></tr></tbody></table><p>抗噪三板斧：<strong>固定种子</strong>（seedrandom 替代 Math.random）、<strong>冻结动画</strong>（测试钩子 freeze 停渲染循环）、<strong>mask 动态区域</strong>（告警列表、时钟不参与对比）。</p><h3 id="_3-实证-三类门禁的分工" tabindex="-1">③ 实证：三类门禁的分工 <a class="header-anchor" href="#_3-实证-三类门禁的分工" aria-label="Permalink to &quot;③ 实证：三类门禁的分工&quot;">​</a></h3><p>CI 门禁不是一条断言，是三道防线：</p><ul><li><strong>结构门禁</strong>：InstancedMesh、楼数、draw calls &lt; 500——抓&quot;忘了实例化&quot;；</li><li><strong>视觉门禁</strong>：默认视角截图 vs 基线——抓&quot;阴影/配色被碰了&quot;；</li><li><strong>性能门禁</strong>：100 帧采样 P95 &lt; 33ms——抓&quot;这栋楼让中端机跑不动&quot;。</li></ul><p>漫画里的实战：阴影偏移 2px，结构与性能断言全绿（它们看不见像素），视觉门禁红灯并产出 diff 图——2341 个差异像素、占比 2%，红块正好圈在楼群阴影区。</p><h3 id="_4-门禁的运营纪律" tabindex="-1">④ 门禁的运营纪律 <a class="header-anchor" href="#_4-门禁的运营纪律" aria-label="Permalink to &quot;④ 门禁的运营纪律&quot;">​</a></h3><ul><li>基线是仓库资产：更新基线单独提交、附 diff 图说明原因；</li><li>便宜的先跑：单测秒级在前，e2e 分钟级在后，反馈越快红灯越有人看；</li><li>帧时间在 CI 虚机（SwiftShader 软渲染）放宽阈值 + 趋势告警，33ms 硬门禁留给 GPU runner 与真机夜跑；</li><li>红灯必须 30 秒能看懂原因，看不懂的红灯迟早被团队绕开。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：截图总有微小差异，阈值放宽又怕漏真回归？</strong> 先固定种子 + freeze 把内容变化降到零；再 mask 掉时钟、告警列表等动态区域；最后用两层参数搭配——threshold 管单像素色差，maxDiffPixelRatio 管差异占比。真回归是成片的红，噪声是零星的点。</li><li><strong>Q：本地 Mac 生成的基线到 Linux CI 全挂？</strong> 渲染栈跨平台不可能逐像素一致。基线必须在与 CI 相同的容器里生成——本地更新基线也用 Playwright 官方 docker 镜像跑，再把 PNG 提交进仓库。</li><li><strong>Q：CI 虚机里 P95 帧时间死活过不了 33ms？</strong> SwiftShader 软渲染比真 GPU 慢 10~50 倍，帧时间没有跨机绝对意义。CI 上硬门禁换成结构量（draw calls、三角形数），帧时间放宽阈值并收集趋势做告警；33ms 的精确验收放在带 GPU 的 runner 或真机夜间任务上。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么视觉回归要求&quot;固定随机种子 + 冻结动画&quot;之后才能截图？</li><li>draw calls 和 P95 帧时间，哪个更适合做无 GPU CI 环境的硬门禁？为什么？</li><li>团队抱怨&quot;门禁老误报，我们直接跳过了&quot;，按本篇的思路应该怎么修？</li></ol><details><summary>答案</summary><ol><li>截图对比的前提是&quot;两次运行的画面本该逐像素一致&quot;。Math.random 每次生成不同布局、动画每帧都在动，差异来自内容本身而非回归，阈值再宽也全是误报。固定种子让内容确定，freeze 让时间确定，剩下的差异才全是渲染层的信号。</li><li>draw calls。它是结构量——由场景内容决定，与 GPU 快慢无关，SwiftShader 下读数与真机一致，适合硬门禁。P95 帧时间在 CI 虚机上被软渲染拖慢 10~50 倍且受邻居负载影响，硬卡 33ms 必然误伤，应放宽阈值、看趋势，精确验收交给有 GPU 的环境。</li><li>门禁的可信度比严格度更重要：① 先降噪——逐个治理偶发失败用例（固定种子、freeze、mask、阈值分层），重试最多 1 次；② 红灯给证据——diff 图、读数要让人 30 秒看懂原因；③ 保留留痕的逃生门——允许 maintainer 豁免但要求写明原因。目标是让团队信门禁，而不是怕门禁。</li></ol></details>',21)])])}const q=a(d,[["render",o]]);export{f as __pageData,q as default};
